const staticData = $getWorkflowStaticData('global');
staticData.listings = [];

return [{
  json: {
    page: 1,
    attempt: 0
  }
}];

const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;
const html = input.data || '';
const config = $('Config').first().json;
const maxPages = config.maxPages;
const testMode = config.testMode;

const idPattern = /AdDetails\?ad=(\d+)/gi;
const foundIds = new Set();
let m;
while ((m = idPattern.exec(html)) !== null) {
  foundIds.add(m[1]);
}

for (const id of foundIds) {
  if (!staticData.listings.some(l => l.adId === id)) {
    staticData.listings.push({ adId: id, url: `https://reklama5.mk/AdDetails?ad=${id}` });
  }
}

const nextPage = (input.page || 1) + 1;
const hasMore = foundIds.size > 0;

// Test Mode only ever looks at search-results page 1, then stops paginating
const shouldContinuePaginating = testMode ? false : (hasMore && nextPage <= maxPages);

return [{
  json: {
    page: nextPage,
    attempt: 0,
    foundOnPage: foundIds.size,
    shouldContinuePaginating
  }
}];

const raw = $input.first().json || {};
const maxRetries = $('Config').first().json.maxRetries;
const page = raw.page || 1;
const attempt = (raw.attempt || 0) + 1;
const errorMessage = (raw.error && (raw.error.message || raw.error)) || raw.message || 'Барањето не успеа (непозната грешка)';

return [{
  json: {
    page,
    attempt,
    lastError: String(errorMessage),
    shouldRetrySearch: attempt <= maxRetries
  }
}];

const raw = $input.first().json;
const searchUrl = `https://reklama5.mk/Search?city=&cat=157&q=&sell=1&buy=0&rent=0&includeforrent=0&trade=0&includeOld=0&includeNew=0&cargoReady=0&DDVIncluded=0&private=0&company=0&page=${raw.page}&SortByPrice=0&pricefrom=100000&priceto=&pageView=`;

return [{
  json: {
    'Чекор': `Преземање страница за пребарување ${raw.page}`,
    'Порака за грешка': raw.lastError || 'Непозната грешка',
    'Линк до оглас': searchUrl,
    'Датум и време': new Date().toISOString(),
    page: raw.page
  }
}];

const raw = $input.first().json;
const config = $('Config').first().json;
const nextPage = (raw.page || 1) + 1;
const shouldContinuePaginating = config.testMode ? false : (nextPage <= config.maxPages);

return [{
  json: {
    page: nextPage,
    attempt: 0,
    shouldContinuePaginating
  }
}];

const staticData = $getWorkflowStaticData('global');
const listings = staticData.listings || [];
return listings.map(l => ({ json: l }));

const existingRows = $input.all().map(i => i.json);
const existingIds = new Set();
for (const row of existingRows) {
  const link = row['Линк до оглас'] || '';
  const match = String(link).match(/ad=(\d+)/);
  if (match) existingIds.add(match[1]);
}

const collected = $('Get Collected Listings').all().map(i => i.json);
let newListings = collected.filter(l => !existingIds.has(l.adId));

const testMode = $('Config').first().json.testMode;
if (testMode) {
  newListings = newListings.slice(0, 10);
}

return newListings.map(l => ({ json: { ...l, attempt: 0 } }));

const html = $json.data || '';

// The HTTP node replaces the item with the response body, so adId/url do not
// survive the fetch - read them back off the current Loop Listings batch item.
const loopItem = $('Loop Listings').first().json || {};
const url = loopItem.url || $json.url || '';
const adId = loopItem.adId || $json.adId || (url.match(/ad=(\d+)/) || [])[1] || '';

function decodeEntities(str) {
  return str
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .trim();
}
function stripTags(str) {
  return decodeEntities(str.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ')).trim();
}

// Reklama5 shows both "495.000 €" and "180,000 €" styles, so the separator
// alone does not tell us thousands vs decimal - decide by group length.
function parsePrice(numStr) {
  const lastSep = Math.max(numStr.lastIndexOf('.'), numStr.lastIndexOf(','));
  if (lastSep === -1) return parseFloat(numStr);
  const tail = numStr.slice(lastSep + 1);
  if (tail.length === 3) {
    return parseFloat(numStr.replace(/[.,]/g, ''));
  }
  const intPart = numStr.slice(0, lastSep).replace(/[.,]/g, '');
  return parseFloat(`${intPart}.${tail}`);
}

const cleanHtml = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ');

// Title (h1)
let title = '';
const h1Match = cleanHtml.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
if (h1Match) title = stripTags(h1Match[1]);

// Price - look in a window right after the h1, fall back to first price-like match on the page
let priceRaw = '';
let priceCurrency = '';
let priceNumeric = null;
const priceRegex = /([\d]{1,3}(?:[.,]\d{3})*(?:[.,]\d+)?)\s*(€|МКД|ден\.?)/i;
if (h1Match) {
  const afterH1 = cleanHtml.slice(h1Match.index + h1Match[0].length, h1Match.index + h1Match[0].length + 1500);
  const priceMatch = afterH1.match(priceRegex);
  if (priceMatch) {
    priceRaw = `${priceMatch[1]} ${priceMatch[2]}`.trim();
    priceCurrency = /€/.test(priceMatch[2]) ? '€' : 'МКД';
    priceNumeric = parsePrice(priceMatch[1]);
  }
}
if (!priceRaw) {
  const anyPrice = cleanHtml.match(priceRegex);
  if (anyPrice) {
    priceRaw = `${anyPrice[1]} ${anyPrice[2]}`.trim();
    priceCurrency = /€/.test(anyPrice[2]) ? '€' : 'МКД';
    priceNumeric = parsePrice(anyPrice[1]);
  }
}

// Date posted
let datePosted = '';
const dateMatch = cleanHtml.match(/(Денес|Вчера|\d{1,2}\.\d{1,2}\.\d{4})\s*,?\s*(\d{1,2}:\d{2})/i);
if (dateMatch) datePosted = `${dateMatch[1]} ${dateMatch[2]}`;

// Location: Cyrillic "Municipality / City" pattern, searched near the date first
let location = '';
const cyr = 'А-ШЀ-ЯЃЌЉЊЏабвгдѓежзѕијклљмнњопрстќуфхцчџш';
const locRegex = new RegExp(`([${cyr}][${cyr}\\s]{1,40})\\/\\s*([${cyr}][${cyr}\\s]{1,40})`, 'u');
if (dateMatch) {
  const around = cleanHtml.slice(Math.max(0, dateMatch.index - 300), dateMatch.index + 300);
  const locMatch = stripTags(around).match(locRegex);
  if (locMatch) location = `${locMatch[1].trim()} / ${locMatch[2].trim()}`;
}
if (!location) {
  const locMatch = stripTags(cleanHtml).match(locRegex);
  if (locMatch) location = `${locMatch[1].trim()} / ${locMatch[2].trim()}`;
}

// Seller / agency block: anchored on the 'Се продава од' label
let sellerName = '';
let sellerType = 'Приватно лице';
let phoneRaw = '';
let phoneSource = 'sidebar';
const phoneRegex = /0\d{1,2}[\s\/\-]?\d{3}[\s\/\-]?\d{3,4}/;

const sellerLabelIdx = cleanHtml.indexOf('Се продава од');
if (sellerLabelIdx !== -1) {
  const block = cleanHtml.slice(sellerLabelIdx, sellerLabelIdx + 2500);
  const hasImage = /<img\b/i.test(block);
  sellerType = hasImage ? 'Агенција' : 'Приватно лице';

  const blockText = stripTags(block).replace(/^Се продава од:?\s*/i, '');
  const phoneMatchInBlock = blockText.match(phoneRegex);
  if (phoneMatchInBlock) {
    phoneRaw = phoneMatchInBlock[0].trim();
    let namePart = blockText.slice(0, phoneMatchInBlock.index).trim();
    namePart = namePart.replace(/Се продава од:?/i, '').trim();
    sellerName = namePart.slice(-80).trim();
  } else {
    sellerName = blockText.slice(0, 80).trim();
  }
}

// Fallback: scan whole page text if the structured sidebar phone wasn't found
if (!phoneRaw) {
  const fullText = stripTags(cleanHtml);
  const fallbackMatch = fullText.match(phoneRegex);
  if (fallbackMatch) {
    phoneRaw = fallbackMatch[0].trim();
    phoneSource = 'fallback-scan';
  }
}

const phoneDigits = phoneRaw.replace(/\D/g, '');
let phoneDisplay = phoneRaw;
if (phoneDigits && phoneDigits !== phoneRaw) {
  phoneDisplay = `${phoneRaw} (${phoneDigits})`;
}

const fullUrl = url.startsWith('http')
  ? url
  : `https://reklama5.mk${url.startsWith('/') ? '' : '/'}${url}`;
const isAllowedHost = fullUrl.startsWith('https://reklama5.mk/');

const priceFrom = $('Config').first().json.priceFrom;
const isValidListing = priceCurrency === '€' && priceNumeric !== null && priceNumeric >= priceFrom && isAllowedHost;

return {
  json: {
    adId,
    title,
    priceRaw,
    priceCurrency,
    priceNumeric,
    location,
    datePosted,
    sellerName,
    sellerType,
    phoneRaw,
    phoneDigits,
    phoneDisplay,
    phoneSource,
    url: fullUrl,
    isAllowedHost,
    isValidListing,
    scrapedAt: new Date().toISOString()
  }
};

return {
  json: {
    'Наслов на оглас': $json.title,
    'Цена': $json.priceRaw,
    'Локација': $json.location,
    'Датум на објавување': $json.datePosted,
    'Име на продавач/агенција': $json.sellerName,
    'Телефон': $json.phoneDisplay,
    'Приватно/Агенција': $json.sellerType,
    'Линк до оглас': $json.url,
    'Датум на извлекување': $json.scrapedAt
  }
};

return {
  json: {
    'Чекор': 'Филтер на валута/цена/домен',
    'Порака за грешка': `Исклучено: цена="${$json.priceRaw}" валута=${$json.priceCurrency || 'непозната'} износ=${$json.priceNumeric} дозволен домен=${$json.isAllowedHost}`,
    'Линк до оглас': $json.url,
    'Датум и време': $json.scrapedAt || new Date().toISOString()
  }
};

const raw = $input.first().json || {};
const maxRetries = $('Config').first().json.maxRetries;

// A failed HTTP item carries the error, not the original url/adId - read those
// back off the current Loop Listings batch item instead.
const loopItem = $('Loop Listings').first().json || {};
const url = loopItem.url || raw.url || '';
const adId = loopItem.adId || raw.adId || (url.match(/ad=(\d+)/) || [])[1] || '';
const attempt = (raw.attempt || 0) + 1;
const errorMessage = (raw.error && (raw.error.message || raw.error)) || raw.message || 'Барањето не успеа (непозната грешка)';

return [{
  json: {
    url,
    adId,
    attempt,
    lastError: String(errorMessage),
    shouldRetryListing: attempt <= maxRetries
  }
}];

const raw = $input.first().json;
const maxRetries = $('Config').first().json.maxRetries;

return [{
  json: {
    'Чекор': `Преземање на детали за оглас (по ${maxRetries} обиди)`,
    'Порака за грешка': raw.lastError || 'Непозната грешка',
    'Линк до оглас': raw.url || '',
    'Датум и време': new Date().toISOString()
  }
}];
